CREATE TABLE site_deliveries (
  site_id uuid PRIMARY KEY REFERENCES sites(id) ON DELETE CASCADE,
  delivered_to text NOT NULL, delivered_at timestamptz NOT NULL,
  recorded_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT site_deliveries_delivered_to_not_blank CHECK (btrim(delivered_to) <> ''));
